import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Data collected and sent","description":"","frontmatter":{},"headers":[],"relativePath":"en/integration/data.md","filePath":"en/integration/data.md","lastUpdated":1794405696000}`),a={name:`en/integration/data.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="data-collected-and-sent" tabindex="-1">Data collected and sent <a class="header-anchor" href="#data-collected-and-sent" aria-label="Permalink to “Data collected and sent”">​</a></h1><h2 id="what-is-observed-automatically" tabindex="-1">What is observed automatically <a class="header-anchor" href="#what-is-observed-automatically" aria-label="Permalink to “What is observed automatically”">​</a></h2><p>Observation happens on collected pages, with the user&#39;s consent and with metadata sending enabled in the site settings. The keys below are the names the SDK holds and uses in decision requests to your own API.</p><table tabindex="0"><thead><tr><th>Observed value</th><th>Key</th><th>Source and unit</th></tr></thead><tbody><tr><td>Page path</td><td><code>page.path</code></td><td><code>location.pathname</code> of the current URL. Example: <code>/products/polo</code></td></tr><tr><td>Page name</td><td><code>page.name</code></td><td>A string taken in the priority order below</td></tr><tr><td>Page description</td><td><code>page.description</code></td><td>A string taken in the priority order below. The key is omitted if nothing is found</td></tr><tr><td>Page type</td><td><code>page.type</code></td><td>A custom JSON-LD candidate, or <code>@type</code> in legacy mode. Omitted in standard mode</td></tr><tr><td>Page themes</td><td><code>page.themes</code></td><td>Taken from a custom JSON-LD candidate or legacy mode. Omitted in standard mode</td></tr><tr><td>Time visible</td><td><code>visibleMs</code></td><td>Cumulative milliseconds per page. Time while the tab is hidden or after <code>pagehide</code> is not added</td></tr><tr><td>Order of views</td><td>Array order of <code>visits[]</code></td><td>From the oldest view to the newest. The latest 50 are kept</td></tr></tbody></table><p><code>visibleMs</code> is time based on the tab&#39;s visibility state. It is not a value that confirms the time actually read or gazed at. The limit per entry is 86,400,000 milliseconds. The date and time of each view, visit IDs and scroll amounts are not recorded.</p><p>Page information is used for <code>currentPage</code>, for the initial decision, and for <code>visits[].page</code>, for views that met the minimum viewing time. For the page at entry, <code>path</code>, <code>name</code> and <code>url</code> are saved to <code>entryPage</code>.</p><h3 id="page-url-and-excluded-keys" tabindex="-1">Page URL and excluded keys <a class="header-anchor" href="#page-url-and-excluded-keys" aria-label="Permalink to “Page URL and excluded keys”">​</a></h3><p><code>page.url</code> is taken from <code>location.href</code>. It includes GET parameters, and if the exclusion setting is empty, all of them are kept. A username, password and anything after <code>#</code> in the URL are always removed. <code>path</code> is the path only, as before.</p><p>In <strong>GET parameter keys not to collect</strong> under &quot;Site settings → Page information fetching&quot;, you can specify up to 50 keys to exclude, each up to 100 characters. The match is exact and case-sensitive, against the URL-decoded key. If the same key appears several times, all are removed. The order and encoding of the parameters that remain are preserved.</p><p>Example: if the excluded keys are <code>email</code> and <code>token</code>, the URL saved and sent from <code>https://example.com/polo?cid=mail_runner&amp;email=a%40example.com&amp;token=x#size</code> is <code>https://example.com/polo?cid=mail_runner</code>. <code>Email</code> is a different key from <code>email</code>. A URL is limited to 4,096 characters. If it is longer, the URL field is omitted and the path and name are kept.</p><p>Exclusion is applied in the SDK before saving, normal sending and diagnostic recording, and your own API checks it again. A URL condition that uses an excluded value is not met. Search terms or personal information in a URL are not detected automatically. If personal information is in the path, set an excluded path.</p><p><code>entryPage</code> is the first collected page observed in this tab after consent. It isn&#39;t inferred from entries before consent or from the HTTP Referer. Even if a later page has no <code>cid</code>, the <code>cid</code> of the saved entry page can still be judged.</p><h3 id="choose-how-it-is-fetched-per-site" tabindex="-1">Choose how it is fetched per site <a class="header-anchor" href="#choose-how-it-is-fetched-per-site" aria-label="Permalink to “Choose how it is fetched per site”">​</a></h3><p>A site admin or superuser can change it under &quot;Site settings → Page information fetching&quot;. A new site is in standard mode. An existing site with no fetching settings keeps the previous JSON-LD-first behavior until you switch and save.</p><h3 id="standard-mode-fetching-priority" tabindex="-1">Standard mode fetching priority <a class="header-anchor" href="#standard-mode-fetching-priority" aria-label="Permalink to “Standard mode fetching priority”">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>First candidate</th><th>Second candidate</th><th>If it can&#39;t be obtained</th></tr></thead><tbody><tr><td><code>page.name</code></td><td><code>content</code> of <code>meta[property=&quot;og:title&quot;]</code> or <code>meta[name=&quot;og:title&quot;]</code></td><td>The HTML <code>title</code></td><td><code>Untitled</code></td></tr><tr><td><code>page.description</code></td><td><code>content</code> of <code>meta[property=&quot;og:description&quot;]</code> or <code>meta[name=&quot;og:description&quot;]</code></td><td><code>content</code> of <code>meta[name=&quot;description&quot;]</code> or <code>meta[property=&quot;description&quot;]</code></td><td>The key is omitted</td></tr><tr><td><code>page.type</code></td><td>Not fetched</td><td>—</td><td>The key is omitted</td></tr><tr><td><code>page.themes</code></td><td>Not fetched</td><td>—</td><td>The key is omitted</td></tr></tbody></table><p>The name and the description are each evaluated in their own order. If a value is empty, isn&#39;t a string or matches the common exclusion patterns, it moves on to the next candidate. Standard mode doesn&#39;t read JSON-LD. It examines up to 200 meta elements and uses only the first element for the same key.</p><h3 id="custom-mode-fetching-priority" tabindex="-1">Custom mode fetching priority <a class="header-anchor" href="#custom-mode-fetching-priority" aria-label="Permalink to “Custom mode fetching priority”">​</a></h3><p>Candidates arranged in the admin console are evaluated from the top, and the first candidate that satisfies its conditions and has a page name is adopted. There are at most 10 candidates, and each candidate has at most 5 conditions.</p><p>For example, you can set this order.</p><table tabindex="0"><thead><tr><th>Order</th><th>Condition</th><th>Page name</th><th>Description</th></tr></thead><tbody><tr><td>1</td><td>JSON-LD <code>@type</code> contains <code>Product</code>, and <code>sku</code> of the same object has a value</td><td><code>Product details: </code> + <code>name</code> of the same JSON-LD</td><td><code>description</code> of the same JSON-LD</td></tr><tr><td>2</td><td><code>og:title</code> has a value</td><td><code>og:title</code></td><td><code>og:description</code></td></tr><tr><td>3</td><td>The HTML title has a value</td><td>The HTML title</td><td>meta description</td></tr></tbody></table><p><code>Product</code> is the schema.org standard. It isn&#39;t automatically converted to <code>Products</code> or <code>ProductGroup</code>. For conditions, you can choose AND/OR and &quot;has a value&quot;, &quot;has the property&quot;, &quot;equals&quot; and &quot;array contains / string matches&quot;. 0 and false exist as values. &quot;Equals&quot; and &quot;contains&quot; are exact matches of the stringified value, not partial matches.</p><p>You can choose the source and key for the page name and description, and a prefix to put before the fetched value. If a description can&#39;t be found, specify either &quot;adopt without a description&quot; or &quot;move on to the next candidate&quot;. If no candidate can be used, the current <code>path</code> and <code>name: &quot;Untitled&quot;</code> are kept and the description is omitted.</p><p>JSON-LD conditions and fetched values are evaluated on the same object. If there are several candidates, it looks for a unique target in this order: the mainEntity of a WebPage that matches the current page, then a url/mainEntityOfPage tied to the current page. If it can&#39;t be determined, it moves on to the next candidate. It doesn&#39;t pick the first product automatically.</p><p>Only when a JSON-LD candidate is adopted, the first string of that candidate&#39;s <code>@type</code> is used for <code>page.type</code>, and <code>articleSection ?? keywords</code> for <code>page.themes</code>. Themes are a string or an array of strings split by commas, up to 8. It doesn&#39;t switch from an empty articleSection to keywords, and it doesn&#39;t remove duplicates. For candidates that use only meta tags or the title, type and themes are omitted.</p><p>JSON-LD is read from the first 10 scripts, each at most 100,000 characters, with a search depth of 8 and at most 200 objects. It examines the top level, arrays, @graph and mainEntity, and doesn&#39;t expand inside itemListElement or follow external references. A key is a simple property reference of up to 6 levels and 120 characters. Expressions, arbitrary JavaScript and DOM selectors can&#39;t be used. Properties used only to check conditions, such as sku, are not added to the API automatically.</p><h3 id="common-formatting-and-exclusion" tabindex="-1">Common formatting and exclusion <a class="header-anchor" href="#common-formatting-and-exclusion" aria-label="Permalink to “Common formatting and exclusion”">​</a></h3><p>Limits are 160 characters for the name, 400 for the description, 80 for the type and 80 for each theme. Consecutive spaces and line breaks become a single space, leading and trailing spaces are removed, and the text is cut at the limit. After that, strings that match an email format, or a run of 9 or more digits, including forms separated by spaces or hyphens, are excluded. The same check applies to a custom prefix.</p><p>This check alone doesn&#39;t remove all personal information. Exclude pages that contain names, addresses or personal metadata from the collected paths.</p><h3 id="changing-settings-and-checking-on-a-real-page" tabindex="-1">Changing settings and checking on a real page <a class="header-anchor" href="#changing-settings-and-checking-on-a-real-page" aria-label="Permalink to “Changing settings and checking on a real page”">​</a></h3><p>The SDK itself is common. The saved per-site rules are applied the next time the settings are fetched, so you don&#39;t need to replace the tag. It isn&#39;t a mechanism that reflects changes immediately in a tab that is already open. If the fetching rule version differs at decision time, the decision isn&#39;t passed on to Jev and is held, and the new SDK fetches the settings again and updates the local data. The decision request for the same page is not sent again.</p><p>When the rule version changes, the earlier browsing history in the browser is discarded and the current page is taken again. The displayed state and the permitted events and confirmed states are kept. An old SDK can&#39;t interpret the new settings, so a reload after the cache updates is needed.</p><p>If you enter a URL on the right, you can receive the result and reasons from the SDK in another tab. You can check even an unsaved draft of the settings. It requires measurement consent, the latest SDK and metadata sending enabled for the site. During a check, normal judgment, offer display and saving history are not performed. For details, see <a href="./../guides/sites#fetching-page-information-and-checking-on-a-real-page">site settings</a>.</p><details class="details custom-block"><summary>The previous specification for existing sites without fetching settings</summary><h3 id="legacy-mode-fetching-priority" tabindex="-1">Legacy mode fetching priority <a class="header-anchor" href="#legacy-mode-fetching-priority" aria-label="Permalink to “Legacy mode fetching priority”">​</a></h3><p>First, one JSON-LD object that represents the page is chosen by the rules described below. Each field uses a property of that object.</p><table tabindex="0"><thead><tr><th>Field</th><th>Order of fetching</th><th>Limit and when there is no value</th></tr></thead><tbody><tr><td><code>name</code></td><td>JSON-LD <code>name</code> → <code>headline</code> → <code>title</code> → meta <code>og:title</code> → HTML <code>document.title</code></td><td>Up to 160 characters. <code>&quot;Untitled&quot;</code> if no usable string is left</td></tr><tr><td><code>description</code></td><td>JSON-LD <code>description</code> → meta <code>og:description</code> → meta <code>description</code></td><td>Up to 400 characters. The key is omitted if there is no usable string</td></tr><tr><td><code>type</code></td><td>The matching type from the selected JSON-LD <code>@type</code></td><td>JSON-LD only. There is no fallback to <code>og:type</code> or similar</td></tr><tr><td><code>themes</code></td><td>JSON-LD <code>articleSection</code> → <code>keywords</code></td><td>Up to 80 characters each, up to 8. JSON-LD only. <code>meta keywords</code> and similar are not used</td></tr></tbody></table><p>Meta information targets both <code>meta[property=&quot;key&quot;]</code> and <code>meta[name=&quot;key&quot;]</code>, and uses the <code>content</code> of the first matching element in the document. For example, <code>og:title</code> can be taken from <code>&lt;meta property=&quot;og:title&quot; content=&quot;…&quot;&gt;</code> or <code>&lt;meta name=&quot;og:title&quot; content=&quot;…&quot;&gt;</code>. Multiple elements with the same key are not combined.</p><p><strong>It moves on to the next candidate only when the previous value does not exist or is <code>null</code>.</strong> Even if the value is an empty string, a non-string such as an array, or matches the exclusion patterns described later, it doesn&#39;t move on. For example, if the JSON-LD has <code>&quot;name&quot;: &quot;&quot;</code>, <code>name</code> becomes <code>&quot;Untitled&quot;</code> even when an OGP title exists.</p><p><code>themes</code> accepts a string or an array of strings, splits it by a half-width comma <code>,</code> and formats it. <code>articleSection</code> and <code>keywords</code> are not combined. If <code>articleSection</code> is an empty string or an empty array, it doesn&#39;t move on to <code>keywords</code> either. Themes are not de-duplicated.</p><h3 id="legacy-mode-json-ld-object-selection" tabindex="-1">Legacy mode JSON-LD object selection <a class="header-anchor" href="#legacy-mode-json-ld-object-selection" aria-label="Permalink to “Legacy mode JSON-LD object selection”">​</a></h3><p>The target is <code>script[type=&quot;application/ld+json&quot;]</code>. The first 10 are read, and any that exceeds 100,000 characters or can&#39;t be parsed as JSON is skipped. The search also has limits such as depth.</p><p>The supported <code>@type</code> values are these 9. They are matched as exact strings. If several types are specified in an array, <strong>the first matching type in the array&#39;s order</strong> is adopted.</p><p><code>WebPage</code>, <code>Article</code>, <code>NewsArticle</code>, <code>BlogPosting</code>, <code>Product</code>, <code>Service</code>, <code>JobPosting</code>, <code>Course</code>, <code>Event</code></p><p>The object is chosen in this order.</p><ol><li>Look for a <code>WebPage</code> whose <code>url</code> or <code>@id</code> matches the current page. If none matches and there is exactly one <code>WebPage</code>, use it.</li><li>If the chosen <code>WebPage</code>&#39;s <code>mainEntity</code> is a supported type, use it as the representative of the page. A reference by <code>@id</code> is resolved to the object with the same <code>@id</code> inside the loaded JSON-LD.</li><li>If that can&#39;t be used, look for a supported non-<code>WebPage</code> object whose <code>url</code> or <code>mainEntityOfPage</code> matches the current page.</li><li>If none is found, use the <code>WebPage</code> chosen in step 1.</li><li>If there is none, and there is exactly one supported object other than <code>WebPage</code>, use it. If there are several and it can&#39;t be determined, no JSON-LD representative is chosen, and each field moves on to its OGP, HTML or other candidates.</li></ol><p>URL matching is decided by origin and path. Differences in the query, fragment and trailing <code>/</code> are not used. A relative URL is also interpreted against the current page. If several match, the first in search order is used. <code>mainEntityOfPage</code> supports a URL string or the form <code>{&quot;@id&quot;:&quot;…&quot;}</code>.</p><p>What is searched is the top-level objects and arrays of the JSON-LD, and their <code>@graph</code> and <code>mainEntity</code>. Products and the like inside <code>itemListElement</code> are not searched. There is no process that accesses external URLs to resolve references.</p><h3 id="string-formatting-and-exclusion" tabindex="-1">String formatting and exclusion <a class="header-anchor" href="#string-formatting-and-exclusion" aria-label="Permalink to “String formatting and exclusion”">​</a></h3><p>For the name, description and each theme, consecutive spaces and line breaks become a single space, leading and trailing spaces are removed, and the text is cut to the limit. After that, strings that match an email format, or a run of 9 or more digits, including forms separated by spaces or hyphens, are not adopted.</p><p>This pattern check alone can&#39;t detect all personal information. If you put names, addresses or personal information in a page&#39;s metadata, you need to take measures such as excluding it from collection.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><p>The current URL is <code>https://example.com/products/polo?from=mail#size</code>, and the following JSON-LD is present.</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;@context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://schema.org&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;@type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;吸汗速乾ポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;さらりと着られる夏向けのポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;keywords&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;吸汗速乾,ポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;offers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;@type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Offer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;price&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3980&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;priceCurrency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JPY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The fetched <code>page</code> has this form. <code>offers.price</code> and <code>priceCurrency</code> are not fetched. The following is an illustrative example, not a measurement from a real site.</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/products/polo?from=mail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/products/polo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;吸汗速乾ポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;さらりと着られる夏向けのポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Product&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;themes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;吸汗速乾&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ポロシャツ&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Image URLs, prices, stock, breadcrumbs, heading text, the full text of the page and JSON-LD <code>about</code> and similar are not used by this automatic extraction. For business states such as applications, bookings and carts, and for custom clicks, explicitly pass the names and values you registered in <a href="./sdk">optional integrations</a>.</p></details><h2 id="what-is-stored-in-the-browser" tabindex="-1">What is stored in the browser <a class="header-anchor" href="#what-is-stored-in-the-browser" aria-label="Permalink to “What is stored in the browser”">​</a></h2><p>The following values are saved in sessionStorage under <code>jev:v1:&lt;site ID&gt;</code>. The key name is kept for compatibility, and the internal <code>version</code> is 2. Measurement of the current page is saved in <code>currentVisit: {page, visibleMs}</code> and is added to <code>visits</code> once it becomes a valid view. <code>entryPage</code> stores the entry page, and <code>urlPolicyRevision</code> stores the version of the URL exclusion settings. If the site ID is <code>demo</code>, the storage key is <code>jev:v1:demo</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Value stored</th></tr></thead><tbody><tr><td><code>visits</code></td><td>An array of <code>page</code> and <code>visibleMs</code> that met the minimum viewing time</td></tr><tr><td><code>actions</code></td><td>An array of <code>{name, value}</code> passed through optional integrations. <code>{name}</code> if the value is omitted</td></tr><tr><td><code>facts</code></td><td>A map of state names passed through optional integrations to boolean or finite number values</td></tr><tr><td><code>delivery</code></td><td><code>{shown, dismissed}</code> per campaign ID: the number of successful displays and whether it was closed</td></tr><tr><td><code>updated</code></td><td>The last save time, in milliseconds from <code>Date.now()</code></td></tr></tbody></table><p>On reload, saved data whose <code>updated</code> is 30 minutes or more old is not restored, and the data is validated again against the currently allowed paths, event names, state names and so on. It isn&#39;t a scheme that stores each view&#39;s date and time and deletes them after 30 minutes. Another tab or device is not linked as one visitor.</p><p>The display limit is not a permanent limit across all devices. It is a limit against the valid history in the browser.</p><p>The fetching rule version is kept together with the history as <code>metadataRevision</code>. For legacy mode it is <code>legacy</code>, and for standard and custom it is a hash of the fetching settings (a 32-character hexadecimal string). When the version changes, the previous <code>visits</code> are discarded.</p><h2 id="what-is-sent-to-your-own-api-at-decision-time" tabindex="-1">What is sent to your own API at decision time <a class="header-anchor" href="#what-is-sent-to-your-own-api-at-decision-time" aria-label="Permalink to “What is sent to your own API at decision time”">​</a></h2><p>The JSON body of <code>POST /v1/decision?siteId=&lt;site ID&gt;</code> carries these keys. Sending happens only at decision time.</p><table tabindex="0"><thead><tr><th>Key</th><th>Contents</th></tr></thead><tbody><tr><td><code>siteId</code></td><td>The site ID given in <code>data-site</code> of the shared tag</td></tr><tr><td><code>visits</code></td><td>Browsing history. Each element is <code>{page, visibleMs}</code>. Past valid views only. The current page is not included</td></tr><tr><td><code>actions</code></td><td>Actions passed through optional integrations under permitted names. Up to the latest 30</td></tr><tr><td><code>facts</code></td><td>States passed through optional integrations under permitted names</td></tr><tr><td><code>delivery</code></td><td>Displayed and closed state per campaign ID</td></tr></tbody></table><p>The new SDK also sends <code>protocolVersion: 2</code>, <code>currentPage</code>, an optional <code>entryPage</code>, the URL exclusion settings version <code>urlPolicyRevision</code> and the fetching rule version <code>metadataRevision</code>. These are values for the API to check against the current versions, and they are not sent to Jev. The source of each value and the reason a candidate was adopted are also not included in normal decision requests or in what goes to Jev.</p><p><code>updated</code> is not sent. The source information (<code>sources</code>) handled by the diagnostic panel is also not included in normal decision requests. You can check each item&#39;s source in the <a href="./../guides/debugging">diagnostic panel</a>.</p><p>Your own API accepts at most 50 <code>visits</code>, 30 <code>actions</code>, 20 <code>facts</code> and 100 <code>delivery</code> campaigns. <code>page.path</code> is accepted up to 512 characters. The SDK doesn&#39;t truncate the path to that length, and if it is exceeded, API validation rejects it. For other limits, see <a href="./../reference/configuration">settings and limits</a>.</p><p>The API validates the permitted and excluded paths, the valid viewing time and count, and the registered event names and state names. It doesn&#39;t pass everything the SDK sent unconditionally to Jev.</p><h2 id="what-is-sent-to-jev" tabindex="-1">What is sent to Jev <a class="header-anchor" href="#what-is-sent-to-jev" aria-label="Permalink to “What is sent to Jev”">​</a></h2><p>Your own API builds the following <code>state</code> from the current and entry pages and the valid past views, and sends it to Jev together with the configured <code>model</code> and the campaign&#39;s <code>questions</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Contents and conversion</th></tr></thead><tbody><tr><td><code>state.last_qualified_page</code></td><td>The last <code>page</code> among the valid views. Name, description, type, themes and so on keep the keys above</td></tr><tr><td><code>state.browsing_history_oldest_first[].page</code></td><td>The page information of each page that met the minimum viewing time and the permitted path conditions, in oldest-first order</td></tr><tr><td><code>state.browsing_history_oldest_first[].visible_seconds</code></td><td>The value converted to seconds with <code>Math.round(visibleMs / 1000)</code></td></tr><tr><td><code>state.actions</code></td><td><code>actions</code> narrowed to the action names allowed by the API</td></tr><tr><td><code>state.facts</code></td><td><code>facts</code> narrowed to the state names allowed by the API</td></tr><tr><td><code>questions</code></td><td><code>{type: &quot;noul&quot;, instructions: &quot;judgment question&quot;}</code> for keys such as <code>c0q0</code></td></tr></tbody></table><p><code>state.current_page</code> is the current page used to decide the initial display. <code>state.entry_page</code> is included only when a saved entry page exists. Both are kept distinct from evidence of &quot;already viewed&quot;. If there are no past valid views, <code>last_qualified_page</code> is omitted and the history is an empty array.</p><p>If the minimum viewing time is 8,000 milliseconds, a past page of 3,000 milliseconds is not added to the new SDK&#39;s history. A view of 12,000 milliseconds becomes <code>visible_seconds: 12</code>. Reaching the minimum viewing time isn&#39;t sent to the server and is used in the next page&#39;s initial decision. If you set a campaign&#39;s required history count to 0, it can be judged on the current and entry pages even without past history.</p><p><code>siteId</code>, <code>delivery</code> and <code>updated</code> are not included in the <code>state</code> used for Jev&#39;s judgment. Which views are used as evidence is tuned by the API-side algorithm. When conditions are insufficient, there is no target campaign, the key isn&#39;t set or a cost limit applies, it holds without asking Jev.</p><p>Even Preview&#39;s fixed judgment and forced previews before delivery don&#39;t send to the real Jev.</p><p>Confirmed conditions, AND/OR and the final display are handled in code. Questions are not allowed to refer to each other&#39;s answers.</p><h2 id="what-is-not-sent-as-it-is" tabindex="-1">What is not sent as it is <a class="header-anchor" href="#what-is-not-sent-as-it-is" aria-label="Permalink to “What is not sent as it is”">​</a></h2><p>Form input, the full text of pages and whole JSON-LD are not sent, and there is no mechanism that automatically takes names or email addresses from forms. GET parameters of URLs are sent by default, so check the values they contain with the exclusion settings. Basic metadata may also contain personal information, so check the information and scope on your real site.</p><h2 id="server-storage" tabindex="-1">Server storage <a class="header-anchor" href="#server-storage" aria-label="Permalink to “Server storage”">​</a></h2><p>There is no visitor ID, visitor session or behavior-history database. Administrators&#39; users, passkey public keys, admin sessions, site memberships and campaigns are stored in a separate admin database.</p><p>Site-only Jev keys are encrypted and stored in a dedicated table of the admin database. Operational records of real Jev calls are also kept: call time, result category, model name, latency and key type. They don&#39;t include URLs, visitor information, what was sent or answers. See <a href="./../guides/jev">the definition and retention of records</a>.</p><p>This doesn&#39;t mean there is nothing in the sending to Jev, in CDN or proxy logs, or in Cloudflare Access authentication logs. The operator also checks external services&#39; retention terms, contracts and settings.</p><p>Handle the information in the diagnostic panel with care, and also read <a href="./../operations/security">secrets and operations</a>.</p><p>The legacy mode&#39;s fetching order corresponds to <a href="https://github.com/manji6/jev-personalization/blob/a51af0efb9b73cf6b5a117021403206099d5c9a3/src/sdk.js" target="_blank" rel="noreferrer">extractPage in the old SDK</a>. The format your own API currently accepts corresponds to the <a href="https://github.com/manji6/jev-personalization/blob/main/src/schema.js" target="_blank" rel="noreferrer">schema</a>, and the conversion for Jev corresponds to <a href="https://github.com/manji6/jev-personalization/blob/main/src/engine.js" target="_blank" rel="noreferrer">prepare in the engine</a>.</p>`,63)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};